#include <stdio.h>

#define MOD 1000000007

int kInversePairs(int n, int k) {
    long long maxPairs = (long long)n * (n - 1) / 2;
    if (k > maxPairs) return 0;

    int dp[1001] = {0};
    int next_dp[1001] = {0};
    dp[0] = 1;

    for (int length = 1; length <= n; ++length) {
        long long window = 0;

        for (int pairs = 0; pairs <= k; ++pairs) {
            window += dp[pairs];
            if (window >= MOD) window -= MOD;

            if (pairs >= length) {
                window -= dp[pairs - length];
                if (window < 0) window += MOD;
            }

            next_dp[pairs] = (int)window;
        }

        for (int pairs = 0; pairs <= k; ++pairs) {
            dp[pairs] = next_dp[pairs];
        }
    }

    return dp[k];
}

