MOD = 1000000007

class Solution:
    def kInversePairs(self, n, k):
        if k > n * (n - 1) // 2:
            return 0

        dp = [1]

        for length in range(1, n + 1):
            current_max = min(k, length * (length - 1) // 2)
            next_dp = [0] * (current_max + 1)
            window = 0

            for pairs in range(current_max + 1):
                if pairs < len(dp):
                    window += dp[pairs]
                    if window >= MOD:
                        window -= MOD

                if pairs >= length and pairs - length < len(dp):
                    window -= dp[pairs - length]
                    if window < 0:
                        window += MOD

                next_dp[pairs] = window

            dp = next_dp

        return dp[k] if k < len(dp) else 0

