const MOD = 1000000007;

function kInversePairs(n, k) {
    if (k > Math.floor(n * (n - 1) / 2)) {
        return 0;
    }

    let dp = new Array(k + 1).fill(0);
    dp[0] = 1;

    for (let length = 1; length <= n; length++) {
        const next = new Array(k + 1).fill(0);
        let window = 0;

        for (let pairs = 0; pairs <= k; pairs++) {
            window = (window + dp[pairs]) % MOD;
            if (pairs >= length) {
                window = (window - dp[pairs - length] + MOD) % MOD;
            }
            next[pairs] = window;
        }

        dp = next;
    }

    return dp[k];
}

